def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    if n < 4:
        if last_opp == 'D':
            return 'D'
        return 'C'

    opp_c = 0
    for _, b in history:
        if b == 'C':
            opp_c += 1

    opp_c12 = 0
    recent = history[-12:]
    for _, b in recent:
        if b == 'C':
            opp_c12 += 1

    opp_rate = opp_c / float(n)

    opp_d_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    cc_streak = 0
    for i in reversed(range(n)):
        if history[i][0] == 'C' and history[i][1] == 'C':
            cc_streak += 1
        else:
            break

    mutual_d_streak = 0
    for i in reversed(range(n)):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_d_streak += 1
        else:
            break

    count_c = 0
    resp_c = 0
    count_d = 0
    resp_d = 0
    start = max(1, n - 20)
    for i in range(start, n):
        prev_my = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_my == 'C':
            count_c += 1
            if cur_opp == 'C':
                resp_c += 1
        else:
            count_d += 1
            if cur_opp == 'C':
                resp_d += 1

    if count_c > 0:
        pC = (resp_c + 1.0) / float(count_c + 2)
    else:
        pC = (opp_c12 + 1.0) / float(13)

    if count_d > 0:
        pD = (resp_d + 1.0) / float(count_d + 2)
    else:
        pD = 0.45

    q = pC if last_my == 'C' else pD

    pure_defector = False
    if opp_c12 == 0:
        if n >= 15 and opp_c == 0:
            pure_defector = True
        elif count_c >= 3 and resp_c == 0 and opp_rate < 0.10:
            pure_defector = True
        elif opp_rate < 0.04:
            pure_defector = True

    forgiving = count_d >= 2 and resp_d >= 2 and pD > 0.60
    exploitable = opp_c12 >= 8 and opp_rate > 0.55 and pC > 0.65 and forgiving
    retaliatory = count_c >= 2 and count_d >= 2 and pC > 0.68 and pD < 0.45

    if n >= 96:
        if pure_defector:
            return 'D'
        if forgiving or exploitable:
            return 'D'
        if n == 98:
            if pC > 0.60 and opp_c12 >= 5:
                return 'C'
            return 'D'
        if n == 97:
            if pC > 0.60 and opp_c12 >= 4:
                return 'C'
            return 'D'
        if q < 0.38:
            return 'D'
        return 'C'

    if pure_defector:
        return 'D'

    if last_my == 'D' and last_opp == 'D' and mutual_d_streak > 0:
        can_reset = (not pure_defector and pC > 0.55 and opp_rate > 0.40 and count_c >= 1 and resp_c >= 1)
        if can_reset and n < 95:
            if mutual_d_streak <= 2:
                return 'C'
            if rng.random() < 0.35:
                return 'C'
            return 'D'

    if q <= 0.30:
        return 'D'

    if q >= 0.68:
        if last_opp == 'C':
            if exploitable:
                return 'D'
            if forgiving and cc_streak >= 2 and opp_c12 >= 8:
                return 'D'
            if opp_c == n and opp_c12 == 12 and pC > 0.85 and n > 30 and n < 90:
                if count_d == 0 and cc_streak >= 14 and rng.random() < 0.03:
                    return 'D'
                if count_d == 1 and resp_d == 1 and pD > 0.60 and cc_streak >= 1 and rng.random() < 0.65:
                    return 'D'
        return 'C'

    if last_opp == 'D':
        if opp_c12 >= 9 and opp_rate > 0.62 and opp_d_streak <= 2 and not retaliatory and not pure_defector:
            if rng.random() < 0.45:
                return 'C'
            return 'D'
        return 'D'

    if last_my == 'D' and opp_c12 >= 8 and pD > 0.58:
        return 'D'

    return 'C'
